import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-07-13","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-07-13","date":"2020-07-13T00:00:00.000Z","updated":"2020-07-14T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","Integration Test","Container Images"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-13.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-13.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-07-13.md"};function a(n,i,s,p,c,h){return t(),r("div",null,[...i[0]||(i[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间：</strong> 2020年7月13日<br><strong>参会人员：</strong> Fezzik, Travis, Oh, Mike, Karen Norma 以及其他相关人员<br><strong>会议主持：</strong> [主持人姓名]</p><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>Rook集成测试问题</strong></p><ul><li>讨论了Rook集成测试因近期更改而中断的问题。</li><li>决定暂时禁用该测试，并计划重新启用。</li><li>Kiefel提交了一个PR，预计将修复该问题。</li><li>后续行动：重新启用并监控测试，确保其正常运行。</li></ul></li><li><p><strong>容器镜像重命名</strong></p><ul><li>讨论了CI构建的容器镜像重命名的问题。</li><li>Deepika上周完成了相关工作，目前镜像重命名功能已恢复正常。</li></ul></li><li><p><strong>Drive Groups功能</strong></p><ul><li>讨论了Drive Groups功能的进展，目前仍在等待上游合并。</li><li>正在进行私有构建的测试，结果良好。</li><li>后续行动：继续等待上游合并，并进行进一步测试。</li></ul></li><li><p><strong>Rook Monitor模块的Placement Specifications</strong></p><ul><li>讨论了Rook Monitor模块中Placement Specifications的实现问题。</li><li>决定使用Kubernetes的Placement Specifications，而非Orchestrator风格的Placement Specifications。</li><li>需要进一步的示例和指导。</li><li>后续行动：提供更多示例，确保正确实现。</li></ul></li><li><p><strong>新成员介绍</strong></p><ul><li>介绍了新成员Karen Norma，她将负责文档工作。</li><li>Karen将专注于Ceph ADM和安装程序的文档，以及与Orchestrator相关的部分。</li><li>后续行动：与Karen建立联系，提供必要的资源和支持。</li></ul></li><li><p><strong>SEF ADM安装指南</strong></p><ul><li>讨论了SEF ADM安装指南的编写，建议与现有文档进行整合。</li><li>后续行动：安排会议，讨论具体细节。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>重新启用并监控Rook集成测试。</li><li>继续推进Drive Groups功能的测试和合并。</li><li>提供更多Placement Specifications的示例和指导。</li><li>与Karen Norma建立联系，支持其文档工作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>监控Rook集成测试的运行情况。</li><li>继续跟进Drive Groups功能的上游合并。</li><li>提供Placement Specifications的示例和指导。</li><li>安排与Karen Norma的会议，讨论文档编写细节。</li></ul><p><strong>会议结束时间：</strong> [具体时间]<br><strong>下次会议预告：</strong> 下周同一时间</p><p><strong>备注：</strong> 请各位参会人员关注邮件和IRC频道，获取更多更新和资源。</p>',10)])])}const _=e(o,[["render",a]]);export{g as __pageData,_ as default};
